import { expect, test, uniqueName, type APIRequestContext } from "../../fixtures";

type DocumentKind = "w9" | "insurance_certificate" | "contract";

function isoDate(daysFromToday: number): string {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() + daysFromToday);
  return d.toISOString().slice(0, 10);
}

async function uploadAndAwaitExtraction(
  api: APIRequestContext,
  vendorId: string,
  kind: DocumentKind,
  filename: string,
  content: string,
): Promise<{ documentId: string; extraction: any }> {
  const upload = await api.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: { name: filename, mimeType: "text/plain", buffer: Buffer.from(content, "utf-8") },
    },
  });
  expect(upload.status(), `upload ${kind}`).toBe(201);
  const documentId = (await upload.json()).id as string;

  await expect
    .poll(
      async () => {
        const res = await api.get(`/api/documents/${documentId}`);
        return (await res.json()).status;
      },
      { message: `${kind} document finishes extraction`, timeout: 30_000 },
    )
    .toBe("extracted");

  const extractionRes = await api.get(`/api/documents/${documentId}/extraction`);
  expect(extractionRes.status(), `fetch ${kind} extraction`).toBe(200);
  return { documentId, extraction: await extractionRes.json() };
}

test(
  "approving an expired insurance certificate extraction fails with insurance_expired",
  { tag: "@REV-07" },
  async ({ apiAs }) => {
    // Arrange: a member creates a vendor with all three documents, insurance expired yesterday
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");
    const vendorName = uniqueName("Expired Insurance Co");
    const yesterday = isoDate(-1);
    const effective = isoDate(-366);

    const created = await member.post("/api/vendors", {
      data: { name: vendorName, category: "services", contact_email: "ops@expired-insurance.test" },
    });
    expect(created.status()).toBe(201);
    const vendorId = (await created.json()).id as string;

    await uploadAndAwaitExtraction(
      member,
      vendorId,
      "w9",
      "w9.txt",
      [
        "Form W-9",
        "Request for Taxpayer Identification Number and Certification",
        `Name: ${vendorName}`,
        "Business Name: " + vendorName,
        "Tax Classification: LLC",
        "TIN: 12-3456789",
        "EIN: 12-3456789",
        "Address: 1 Main Street, Springfield, IL 62701",
        `Signature Date: ${effective}`,
      ].join("\n"),
    );

    const insurance = await uploadAndAwaitExtraction(
      member,
      vendorId,
      "insurance_certificate",
      "insurance-certificate.txt",
      [
        "Certificate of Liability Insurance",
        `Insured: ${vendorName}`,
        "Insurer: Acme Mutual Insurance",
        "Policy Number: POL-123456",
        "Coverage Amount: 1000000",
        `Effective Date: ${effective}`,
        `Expiration Date: ${yesterday}`,
        `Expiry Date: ${yesterday}`,
      ].join("\n"),
    );

    await uploadAndAwaitExtraction(
      member,
      vendorId,
      "contract",
      "contract.txt",
      [
        "Master Services Agreement",
        `Parties: Northwind Supply and ${vendorName}`,
        `Vendor: ${vendorName}`,
        `Effective Date: ${effective}`,
        "Term: 24 months",
        "Signed: Yes",
      ].join("\n"),
    );

    // Precondition: the insurance extraction captured yesterday as the expiry date
    const insuranceFieldValues = Object.values(
      insurance.extraction.fields as Record<string, { value: string | null }>,
    ).map((f) => f.value ?? "");
    expect(
      insuranceFieldValues.some((v) => v.includes(yesterday)),
      "insurance extraction includes the expiry date from yesterday",
    ).toBe(true);
    expect(insurance.extraction.status).toBe("pending_review");

    const submitted = await member.post(`/api/vendors/${vendorId}/submit`);
    expect(submitted.status()).toBe(200);
    expect((await submitted.json()).status).toBe("in_review");

    // Act: reviewer approves the insurance certificate extraction
    const response = await reviewer.post(`/api/extractions/${insurance.extraction.id}/decision`, {
      data: { decision: "approve" },
    });

    // Assert
    expect(response.status()).toBe(409);
    expect((await response.json()).error.code).toBe("insurance_expired");
  },
);
